export class V1_0OrderOrderSpend {
  public Script: Script;
  constructor(
    proxyPolicyId: PolicyId,
    protocolScripthash: ScriptHash,
    trace?: boolean = false,
  ) {
    this.Script = cborToScript(
      applyParamsToScript(
        trace
          ? ""
          : "",
        Type.Tuple([PolicyId, ScriptHash]),
        [proxyPolicyId, protocolScripthash],
      ),
      "PlutusV3",
    );
  }
}
