export class V1_0StakingVaultStakingVaultMint {
  public Script: Script;
  constructor(
    utxoRef: OutputReference,
    proxyPolicyId: PolicyId,
    trace?: boolean = false,
  ) {
    this.Script = cborToScript(
      applyParamsToScript(
        trace
          ? ""
          : "",
        Type.Tuple([
          Type.Object(
            {
              transaction_id: Type.String(),
              output_index: Type.BigInt(),
            },
            { ctor: 0n },
          ),
          PolicyId,
        ]),
        [utxoRef, proxyPolicyId],
      ),
      "PlutusV3",
    );
  }
}
